{
  "model": "{{ $json.model }}",
  "prompt": "You are an AI Director Planner. Given the following intent and context, create a structured execution plan with clear steps.

Intent: {{ $json.intent }}
Context: {{ $json.context }}

Return ONLY valid JSON in this format:
{
  "steps": [
    {
      "step_id": "step-1",
      "step_title": "<title>",
      "step_description": "<detailed description of what to generate>"
    }
  ]
}",
  "stream": false
}

