const response = $input.first().json;
let planText = response.response || '';

// Clean up markdown fences
planText = planText.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();

try {
  const plan = JSON.parse(planText);
  const steps = plan.steps || plan;
  // Return array of items for splitInBatches-like processing
  return steps.map((step, index) => ({
    json: {
      step_id: step.step_id || `step-${index + 1}`,
      step_title: step.step_title || 'Untitled Step',
      step_description: step.step_description || '',
      model: $input.first().json.model,
      target_path: $input.first().json.target_path,
      intent: $input.first().json.intent,
      context: $input.first().json.context
    }
  }));
} catch (e) {
  throw new Error('Failed to parse planner output: ' + e.message + '\nRaw output: ' + planText);
}

