const response = $input.first().json;
let outputText = response.response || '';

// Clean up markdown fences
outputText = outputText.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();

try {
  const output = JSON.parse(outputText);
  return [{
    json: {
      content: output.content,
      reasoning: output.reasoning,
      filename: output.filename || 'output.txt',
      step_id: $input.first().json.step_id,
      step_title: $input.first().json.step_title,
      step_description: $input.first().json.step_description,
      target_path: $input.first().json.target_path,
      model: $input.first().json.model,
      intent: $input.first().json.intent,
      context: $input.first().json.context
    }
  }];
} catch (e) {
  throw new Error('Failed to parse executor output: ' + e.message + '\nRaw output: ' + outputText);
}

const now = new Date();
const timestamp = now.toISOString().replace(/[:.]/g, '-').slice(0, -5);
const logFilename = `${timestamp}-step-${$input.first().json.step_id}.md`;

const cotLog = `# Step: ${$input.first().json.step_title}

## Metadata
- **Step ID**: ${$input.first().json.step_id}
- **Timestamp**: ${now.toISOString()}
- **Model**: ${$input.first().json.model}
- **Intent**: ${$input.first().json.intent}
- **Target Path**: ${$input.first().json.target_path}

## Step Description
${$input.first().json.step_description}

## Chain of Thought
${$input.first().json.reasoning}

## Generated Content
\`\`\`
${$input.first().json.content}
\`\`\`

## Output File
- **Filename**: ${$input.first().json.filename}
- **Full Path**: ${$input.first().json.target_path}/${$input.first().json.filename}
`;

return [{
  json: {
    logFilename: logFilename,
    logContent: cotLog,
    output_file: $input.first().json.target_path + '/' + $input.first().json.filename,
    step_title: $input.first().json.step_title,
    log_path: 'D:/ToE/ObsidianVaults/AsherGraves/Director Logs/' + logFilename
  }
}];

return [{
  json: {
    status: 'success',
    output_file: $input.first().json.output_file,
    log_file: $input.first().json.log_path,
    step_title: $input.first().json.step_title
  }
}];
